"""Migration of Meridian CRM 4.2 order validation rules ORD-001 through ORD-005."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    """Return a legacy field value, treating missing/NULL values as empty strings."""
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion: empty values compare as zero."""
    if value == "" or value is None:
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Implement legacy LOOKUP, including live-row-only visibility."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if _value(row, "DEL_FLG") == "Y":
            continue
        if _value(row, key_column) == key_value:
            return _value(row, output_column)

    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order record using the applicable legacy rules in file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        disc_pct = _number(_value(record, "DISC_PCT"))

        # ORD-001: INSERT, UPDATE
        if event in ("INSERT", "UPDATE"):
            if not (disc_pct >= Decimal("0") and disc_pct <= Decimal("100")):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        # ORD-002: UPDATE
        if event == "UPDATE":
            owner_role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if (
                disc_pct > Decimal("20")
                and owner_role != "MGR"
                and owner_role != "ADMIN"
            ):
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": "BLOCK",
                    }
                )

        # ORD-003: UPDATE
        if event == "UPDATE":
            if (
                _value(old, "STAT_CD") == "I"
                and _value(record, "STAT_CD") != "I"
                and _value(record, "STAT_CD") != "X"
            ):
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        # ORD-004: INSERT, UPDATE
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > Decimal("0")):
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        # ORD-005: INSERT
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether the collected validation failures contain a BLOCK failure."""
    return any(error.get("severity") == "BLOCK" for error in errors)
